<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {cents,scaled,quoteLineAmount} from './commerceAmounts';
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
type Product={id:string;sku:string;name:string;unit:string;priceCents:number};
type Line={productId:string;sku:string;name:string;unit:string;quantity:string;price:string;discount:string;description:string;amountCents:number};
const props=defineProps<{opportunity:{id:string;version:number;stage:string};request:Request;canWrite:boolean;productRead:boolean}>();
const emit=defineEmits<{updated:[value:{version:number;amountCents:number}]}>();
const lines=ref<Line[]>([]),initialCount=ref(0),products=ref<Product[]>([]),query=ref(''),page=ref(1),total=ref(0),chosen=ref(''),busy=ref(false),error=ref(''),notice=ref('');
const editable=computed(()=>props.canWrite&&props.productRead&&!['WON','LOST'].includes(props.opportunity.stage));
const amount=computed(()=>{try{return lines.value.reduce((sum,l)=>sum+quoteLineAmount(l.quantity,l.price,l.discount),0);}catch{return 0;}});
const money=(v:number)=>'¥'+(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
async function load(){error.value='';const result=await props.request<any[]>(`/opportunities/${props.opportunity.id}/lines`);lines.value=result.map(r=>({productId:r.productId,sku:r.skuSnapshot,name:r.nameSnapshot,unit:r.unitSnapshot,quantity:String(r.quantity),price:(r.unitPriceCents/100).toFixed(2),discount:(r.discountBps/100).toFixed(2),description:r.description,amountCents:r.amountCents}));initialCount.value=lines.value.length;}
async function catalog(){if(!props.productRead||!editable.value)return;const r=await props.request<{items:Product[];total:number}>(`/products?status=ACTIVE&page=${page.value}&pageSize=20&q=${encodeURIComponent(query.value)}`);products.value=r.items;total.value=r.total;}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'请求失败';}finally{busy.value=false;}}
function add(){const p=products.value.find(x=>x.id===chosen.value);if(!p)return;if(lines.value.some(x=>x.productId===p.id)){error.value='同一产品请在原行修改数量';return;}if(lines.value.length>=100){error.value='最多100行';return;}lines.value.push({productId:p.id,sku:p.sku,name:p.name,unit:p.unit,quantity:'1',price:(p.priceCents/100).toFixed(2),discount:'0',description:'',amountCents:0});chosen.value='';}
function save(){return run(async()=>{const payload={expectedVersion:props.opportunity.version,lines:lines.value.map(l=>({productId:l.productId,quantity:l.quantity,unitPriceCents:cents(l.price),discountBps:Number(scaled(l.discount,2)),description:l.description}))};const result=await props.request<{version:number;amountCents:number}>(`/opportunities/${props.opportunity.id}/lines`,'PUT',payload);emit('updated',result);await load();notice.value='产品明细和预计金额已保存';});}
watch(()=>props.opportunity.id,()=>{lines.value=[];products.value=[];notice.value='';run(async()=>{await load();await catalog();});},{immediate:true});
</script>
<template>
 <section class="op-lines"><h3>产品 / 服务明细</h3><p>方案讨论及后续阶段需要明细；保存后预计金额按明细自动汇总。已批准报价的明细锁定。</p>
 <div v-if="error" class="op-error" role="alert">{{error}}</div><div v-if="notice" class="op-ok" role="status">{{notice}}</div>
 <div v-if="editable" class="op-catalog"><input v-model="query" type="search" maxlength="100" placeholder="搜索产品或编码" aria-label="搜索商机产品" @keydown.enter.prevent="page=1;run(catalog)"/><button type="button" :disabled="busy" @click="page=1;run(catalog)">查找</button><select v-model="chosen" aria-label="选择商机产品"><option value="">选择产品或服务</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.sku}} · {{p.name}} · {{money(p.priceCents)}}</option></select><button type="button" :disabled="busy||!chosen" @click="add">添加</button><small>第 {{page}} 页 · {{total}} 项</small><button type="button" :disabled="busy||page<=1" @click="page--;run(catalog)">上一页</button><button type="button" :disabled="busy||page*20>=total" @click="page++;run(catalog)">下一页</button></div>
 <div v-for="(line,index) in lines" :key="line.productId" class="op-line"><strong>{{index+1}}. {{line.name}} · {{line.sku}}</strong><div class="op-fields"><label>数量<input v-model="line.quantity" :disabled="!editable||busy" inputmode="decimal" maxlength="12"/></label><label>含税单价（元）<input v-model="line.price" :disabled="!editable||busy" inputmode="decimal" maxlength="13"/></label><label>折扣（%）<input v-model="line.discount" :disabled="!editable||busy" inputmode="decimal" maxlength="6"/></label><button v-if="editable" type="button" :disabled="busy" @click="lines.splice(index,1)">移除</button></div><label>说明<input v-model="line.description" :disabled="!editable||busy" maxlength="300"/></label></div>
 <p v-if="!lines.length">暂无产品明细，可先维护产品目录后添加。移除全部已有明细会将预计金额归零。</p><div class="op-total"><span>预计金额 {{money(amount)}}</span><button v-if="editable" type="button" class="btn primary" :disabled="busy||(!lines.length&&!initialCount)" @click="save">保存明细</button></div>
 </section>
</template>
<style scoped>
.op-lines{margin:20px 0;padding:18px;border:1px solid #d7e3db;border-radius:10px;background:#f5f8f6}.op-lines h3{margin:0 0 8px;font-size:17px}.op-lines p,.op-lines small{font-size:12px;line-height:1.8;color:#698070}.op-catalog,.op-fields,.op-total{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:14px 0}.op-catalog input{flex:1;min-width:170px}.op-catalog select{flex:1;min-width:170px}.op-line{border-top:1px solid #dce6df;padding:15px 0}.op-line strong{font-size:13px}.op-fields label,.op-line>label{display:flex;flex-direction:column;gap:5px;font-size:12px;min-width:120px;flex:1}.op-fields input,.op-line>label input,.op-catalog input,.op-catalog select{width:100%;padding:8px;border:1px solid #bdcfc2;border-radius:6px;background:#fff;color:#22382e}.op-catalog button,.op-fields button{padding:8px 10px;border:1px solid #bdcfc2;border-radius:6px}.op-total{justify-content:space-between;font-weight:600}.op-error{color:#b5323c}.op-ok{color:#296b4a}@media(max-width:600px){.op-fields label{min-width:100%}}
</style>
